package org.sleepwell.app;

import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

/** Private preferences and pure admission only. No provider reads or OS alarms. */
public final class CalendarRulesStorageTest {
    interface Task{void run(Context context)throws Exception;}
    void fixture(Task task)throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));
        Context real=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="calendar-fixture-"+UUID.randomUUID();Map<String,?> before=new HashMap<>(Prefs.of(real).getAll());CalendarPolicy.Snapshot old=CalendarAlarms.snapshot;
        Context isolated=new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return real.getSharedPreferences(name,mode);}};
        try{task.run(isolated);}finally{CalendarAlarms.snapshot=old;assertTrue(real.deleteSharedPreferences(name));assertEquals(before,Prefs.of(real).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}
    }
    CalendarPolicy.Rules rules(){return new CalendarPolicy.Rules(true,Set.of(4L),Set.of(8L),30,180,"revision-one");}
    Alarm alarm(){Alarm a=new Alarm(9);a.enabled=true;a.hour=7;a.minute=0;a.smartWindow=30;a.days.addAll(Set.of(1,2,3,4,5,6,7));return a;}
    @Test public void selectionRoundTripsAndMalformedSettingsStayReviewable()throws Exception{fixture(c->{assertFalse(CalendarSettings.load(c).enabled);CalendarSettings.save(c,rules());CalendarPolicy.Rules reopened=CalendarSettings.load(c);assertEquals(Set.of(4L),reopened.holidays);assertEquals(Set.of(8L),reopened.meetings);assertEquals(30,reopened.preparation);assertEquals(180,reopened.advance);for(Object invalid:new Object[]{"30",30.5,true,JSONObject.NULL}){JSONObject j=new JSONObject(CalendarSettings.encode(reopened));j.put("preparation",invalid);String raw=j.toString();assertThrows(IllegalArgumentException.class,()->CalendarSettings.decode(raw));}JSONObject extra=new JSONObject(CalendarSettings.encode(reopened)).put("surprise",true);assertThrows(IllegalArgumentException.class,()->CalendarSettings.decode(extra.toString()));CalendarSettings.prefs(c).edit().putString("rules","{bad").commit();assertThrows(IllegalArgumentException.class,()->CalendarSettings.load(c));assertEquals("{bad",CalendarSettings.prefs(c).getString("rules",""));});}
    @Test public void adjustedAdmissionConsumesOriginalHourAndRejectsStaleReceipts()throws Exception{fixture(c->{CalendarSettings.save(c,rules());Alarm a=alarm();ZoneId zone=ZoneId.of("Asia/Riyadh");long base=Instant.parse("2026-10-25T04:00:00Z").toEpochMilli(),early=base-3600000;CalendarAlarms.scheduled(c,a,new CalendarPolicy.Plan(base,base,early,0,"Earlier","revision-one"));assertTrue(CalendarAlarms.eligible(c,a,early,early,0,zone));assertFalse(CalendarAlarms.eligible(c,a,early,early-1800001,0,zone));assertEquals(base,CalendarAlarms.consumed(c,a,early));assertTrue(a.next(CalendarAlarms.consumed(c,a,early),zone)>base);assertFalse(CalendarAlarms.eligible(c,a,early,early,base,zone));a.hour=8;assertFalse(CalendarAlarms.eligible(c,a,early,early,0,zone));a.hour=7;CalendarSettings.save(c,new CalendarPolicy.Rules(true,Set.of(4L),Set.of(8L),30,180,"changed"));assertFalse(CalendarAlarms.eligible(c,a,early,early,0,zone));});}
    @Test public void selectedHolidayMovesToNextRealOccurrenceAndOneTimeRemainsIndependent()throws Exception{fixture(c->{CalendarSettings.save(c,rules());Alarm a=alarm();ZoneId z=ZoneId.systemDefault();long now=System.currentTimeMillis(),base=a.next(now,z);LocalDate day=Instant.ofEpochMilli(base).atZone(z).toLocalDate();long begin=day.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();CalendarAlarms.snapshot=new CalendarPolicy.Snapshot(day.minusDays(1).atStartOfDay(z).toInstant().toEpochMilli(),day.plusDays(10).atStartOfDay(z).toInstant().toEpochMilli(),now,z,"revision-one",List.of(new CalendarPolicy.Event(4,begin,begin+86400000L,true)));CalendarPolicy.Plan plan=CalendarAlarms.plan(c,a,base,now);assertEquals(1,plan.skipped);assertTrue(plan.deadline>base);CalendarAlarms.scheduled(c,a,plan);assertTrue(CalendarAlarms.eligible(c,a,plan.deadline,plan.deadline,0,z));a.days.clear();assertEquals(base,CalendarAlarms.plan(c,a,base,now).deadline);});}
    @Test public void shiftedSkipExpiryUsesOwnedActualDeadlineAndOrdinaryScheduleClearsReceipt()throws Exception{fixture(c->{CalendarSettings.save(c,rules());Alarm a=alarm();ZoneId z=ZoneId.systemDefault();long ordinary=a.next(System.currentTimeMillis(),z),early=ordinary-3600000;LocalDate date=Instant.ofEpochMilli(ordinary).atZone(z).toLocalDate();a.skip=new AlarmSkip("11111111-1111-4111-8111-111111111111",date,a.hour,a.minute,a.days,z.getId());CalendarAlarms.recordSkip(c,a,early);assertEquals(early,CalendarAlarms.skippedDeadline(c,a,ordinary));a.skip=new AlarmSkip("22222222-2222-4222-8222-222222222222",date,a.hour,a.minute,a.days,z.getId());assertEquals(ordinary,CalendarAlarms.skippedDeadline(c,a,ordinary));CalendarAlarms.scheduled(c,a,new CalendarPolicy.Plan(ordinary,ordinary,early,0,"Earlier","revision-one"));CalendarAlarms.scheduled(c,a,CalendarPolicy.ordinary(ordinary,""));assertFalse(CalendarSettings.prefs(c).contains("receipt_"+a.id));});}
}
